  1	/**
  2	 * src/builders/persona-builder.ts
  3	 *
  4	 * Core build orchestrator for @mistralys/persona-builder.
  5	 *
  6	 * Exports three public functions:
  7	 *
  8	 *  1. buildPersona(personaYamlPath, suiteName, suiteConfig, sharedMeta,
  9	 *                  partialsMap, config, plugins, target, agentMap?)
 10	 *     — Builds a single persona for a single target. Returns a BuildResult.
 11	 *
 12	 *  2. buildSuite(suiteName, suiteConfig, config, plugins, target, agentMap?)
 13	 *     — Discovers all persona YAMLs for a suite, fires onSuiteInit, maps
 14	 *       buildPersona() over each, and returns BuildResult[].
 15	 *
 16	 *  3. build(config)
 17	 *     — Top-level entry point. Pre-scans all suites to build a cross-suite
 18	 *       agent name map, then iterates all suites × targets, calls
 19	 *       buildSuite() for each combination, and returns a BuildSummary.
 20	 *       Respects --check (no writes) and --strict (fail on warnings/errors).
 21	 */
 22	
 23	import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
 24	import { existsSync } from 'node:fs';
 25	import path from 'node:path';
 26	import yaml from 'js-yaml';
 27	
 28	import { resolvePartials } from '../engine/partials.js';
 29	import { resolveConditionals } from '../engine/conditionals.js';
 30	import { resolveVariables } from '../engine/variables.js';
 31	import {
 32	  collapseBlankLines,
 33	  ensureBlankLineBeforeHeadings,
 34	  normalizeNewlines,
 35	} from '../engine/postProcessor.js';
 36	import { serializeTools, serializeToolsList } from '../engine/serializer.js';
 37	import { loadPartials } from '../loaders/partials-loader.js';
 38	import {
 39	  runSuiteInit,
 40	  runBuildContext,
 41	  runPostRender,
 42	  runValidate,
 43	} from '../plugins/runner.js';
 44	
 45	import { resolveFrontmatterTemplate, renderFrontmatter } from './frontmatter.js';
 46	import type { BuildConfig, BuildResult, BuildSummary } from './types.js';
 47	import type { PersonaBuildPlugin, PersonaMetadata, SuiteConfig, TargetType, ValidationResult } from '../plugins/types.js';
 48	import { defaultRegistry } from '../targets/built-in.js';
 49	import type { TargetDefinition } from '../targets/types.js';
 50	import type { TargetRegistry } from '../targets/registry.js';
 51	
 52	// ---------------------------------------------------------------------------
 53	// Internal helpers
 54	// ---------------------------------------------------------------------------
 55	
 56	/**
 57	 * Discover all persona YAML files in the `meta/` subdirectory of a suite.
 58	 *
 59	 * Excludes files whose names start with `_` (shared metadata files such as
 60	 * `_shared.yaml`).  Results are sorted lexicographically.
 61	 *
 62	 * @param suiteConfig  Suite configuration (used to locate `metaSubdir`)
 63	 * @returns            Absolute paths to each persona YAML file, sorted.
 64	 */
 65	async function discoverSuitePersonaYamls(suiteConfig: SuiteConfig): Promise<string[]> {
 66	  const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
 67	  const metaDir = path.join(suiteConfig.srcDir, metaSubdir);
 68	
 69	  const entries = await readdir(metaDir, { withFileTypes: true });
 70	
 71	  return entries
 72	    .filter((e) => e.isFile() && e.name.endsWith('.yaml') && !e.name.startsWith('_'))
 73	    .map((e) => path.join(metaDir, e.name))
 74	    .sort();
 75	}
 76	
 77	/**
 78	 * Load and parse a raw YAML file into a plain object.
 79	 * Used for `_shared.yaml` which does not conform to PersonaMetadata's
 80	 * `name` requirement.
 81	 *
 82	 * @param filePath  Absolute path to the YAML file
 83	 * @returns         Parsed object, or {} when the file is empty/absent
 84	 */
 85	async function loadRawYaml(filePath: string): Promise<Record<string, unknown>> {
 86	  if (!existsSync(filePath)) return {};
 87	  const raw = await readFile(filePath, 'utf8');
 88	  const parsed: unknown = yaml.load(raw);
 89	  if (parsed === null || parsed === undefined) return {};
 90	  if (typeof parsed !== 'object' || Array.isArray(parsed)) return {};
 91	  return parsed as Record<string, unknown>;
 92	}
 93	
 94	/**
 95	 * Load a persona YAML file and return it as a plain metadata record.
 96	 * The `name` field is derived from the filename stem when absent.
 97	 *
 98	 * @param yamlPath  Absolute path to the persona YAML file
 99	 * @returns         Merged metadata record ready for context building
100	 */

251	  configVariables?: Record<string, unknown>,
252	  suiteVariables?: Record<string, unknown>,
253	): Record<string, unknown> {
254	  const version =
255	    typeof personaMeta['version'] === 'string'
256	      ? personaMeta['version']
257	      : typeof sharedMeta['default_version'] === 'string'
258	        ? sharedMeta['default_version']
259	        : '0.0.0';
260	
261	  // Merge base: configVariables first (lowest priority), then suiteVariables,
262	  // then sharedMeta, then personaMeta (highest priority among YAML sources).
263	  const merged: Record<string, unknown> = {
264	    ...(configVariables ?? {}),
265	    ...(suiteVariables ?? {}),
266	    ...sharedMeta,
267	    ...personaMeta,
268	    version,
269	  };
270	
271	  // ── Derived convenience fields (only set when not already provided) ───────
272	  // tools_list / tools_json — serialized from the `tools` array if present
273	  const tools = Array.isArray(merged['tools']) ? (merged['tools'] as string[]) : [];
274	  if (!('tools_list' in merged)) {
275	    merged['tools_list'] = serializeToolsList(tools);
276	  }
277	  if (!('tools_json' in merged)) {
278	    merged['tools_json'] = serializeTools(tools);
279	  }
280	
281	  // cc_tools_list / cc_tools_json — from `cc_tools` or fall back to `tools`
282	  const ccTools = Array.isArray(merged['cc_tools']) ? (merged['cc_tools'] as string[]) : tools;
283	  if (!('cc_tools_list' in merged)) {
284	    merged['cc_tools_list'] = serializeToolsList(ccTools);
285	  }
286	  if (!('cc_tools_json' in merged)) {
287	    merged['cc_tools_json'] = serializeTools(ccTools);
288	  }
289	
290	  // cc_file_name_stem — stem of cc_file_name (for default CC frontmatter template)
291	  if (!('cc_file_name_stem' in merged) && typeof merged['cc_file_name'] === 'string') {
292	    const ccFileName = merged['cc_file_name'] as string;
293	    merged['cc_file_name_stem'] = ccFileName.replace(/\.md$/, '');
294	  }
295	
296	  // da_file_name_stem — stem of da_file_name (for deep-agents output)
297	  if (!('da_file_name_stem' in merged) && typeof merged['da_file_name'] === 'string') {
298	    const daFileName = merged['da_file_name'] as string;
299	    merged['da_file_name_stem'] = daFileName.replace(/\.md$/, '');
300	  }
301	
302	  // da_tools_list / da_tools_json — from `da_tools` or fall back to `tools`
303	  // Intentionally gated on da_file_name: unlike cc_tools_list/cc_tools_json (always emitted for
304	  // every persona), da_* fields are absent when the persona has no deep-agents output file (AC-4).
305	  if (typeof merged['da_file_name'] === 'string') {
306	    const daTools = Array.isArray(merged['da_tools']) ? (merged['da_tools'] as string[]) : tools;
307	    if (!('da_tools_list' in merged)) {
308	      merged['da_tools_list'] = serializeToolsList(daTools);
309	    }
310	    if (!('da_tools_json' in merged)) {
311	      merged['da_tools_json'] = serializeTools(daTools);
312	    }
313	  }
314	
315	  // ── Cross-suite agent name variables ──────────────────────────────────────
316	  for (const [key, value] of Object.entries(agentMap)) {
317	    if (!(key in merged)) {
318	      merged[key] = value;
319	    }
320	  }
321	
322	  // ── Target flag injection ─────────────────────────────────────────────────
323	  if (target !== undefined) {
324	    if (registry && registry.has(target)) {
325	      // Inject all contextFlags declared in the target's registry definition.
326	      const flags = registry.get(target).contextFlags ?? {};
327	      for (const [key, value] of Object.entries(flags)) {
328	        merged[key] = value;
329	      }
330	    } else {
331	      // Fallback for targets not present in the registry.
332	      merged[`target_${target.replace(/-/g, '_')}`] = true;
333	    }
334	  }
335	
336	  return merged;
337	}
338	
339	// ---------------------------------------------------------------------------
340	// buildPersona — single persona × single target
341	// ---------------------------------------------------------------------------
342	
343	/**
344	 * Build a single persona for a single output target.
345	 *
346	 * Pipeline:
347	 *   1. Load sharedMeta + personaMeta (callers supply pre-loaded values)
348	 *   2. Build merged context
349	 *   3. Run onBuildContext plugin hooks (context accumulation)
350	 *   4. Resolve frontmatter template → render frontmatter
351	 *   5. Load content template
352	 *   6. Render body: partials → conditionals → variables → post-process
353	 *   7. Assemble final output (frontmatter + body)
354	 *   8. Run onPostRender plugin hooks (output chain)
355	 *   9. Run onValidate plugin hooks (validation collection)
356	 *  10. Determine output file path
357	 *  11. Write output file (unless check mode)
358	 *  12. Return BuildResult
359	 *
360	 * @param personaYamlPath  Absolute path to the persona YAML source file
361	 * @param suiteName        Identifier for the suite this persona belongs to
362	 * @param suiteConfig      Suite configuration object
363	 * @param sharedMeta       Pre-loaded `_shared.yaml` contents
364	 * @param partialsMap      Pre-loaded partials map (shared + suite-local merged)
365	 * @param config           Top-level BuildConfig
366	 * @param plugins          Registered plugins
367	 * @param target           Target output format
368	 * @param agentMap         Pre-built cross-suite agent name map
369	 * @param registry         Target registry to use. Defaults to `defaultRegistry`.
370	 *   **Two-registry limitation:** If you pass a custom `TargetRegistry` only
371	 *   to `build()` (via `config.targetRegistry`) and call `buildPersona()`
372	 *   directly without also passing that registry here, your custom targets
373	 *   will not be visible — `defaultRegistry` will be used instead. Either
374	 *   pass the same registry instance explicitly, or call `build()` to have
375	 *   the registry forwarded automatically.
376	 * @returns                BuildResult for this persona × target combination
377	 */
378	export async function buildPersona(
379	  personaYamlPath: string,
380	  suiteName: string,
381	  suiteConfig: SuiteConfig,
382	  sharedMeta: Record<string, unknown>,
383	  partialsMap: Record<string, string>,
384	  config: BuildConfig,
385	  plugins: PersonaBuildPlugin[],
386	  target: string,
387	  agentMap: Record<string, string> = {},
388	  registry: TargetRegistry = defaultRegistry,
389	): Promise<BuildResult> {
390	  // ── 1. Load persona metadata ──────────────────────────────────────────────
391	  const personaMeta = await loadPersonaYaml(personaYamlPath);
392	
393	  // ── 2. Build merged context ───────────────────────────────────────────────
394	  let context = buildContext(
395	    personaMeta,
396	    sharedMeta,
397	    agentMap,
398	    target,
399	    registry,
400	    config.variables,

401	    suiteConfig.variables,
402	  );
403	
404	  // ── 3. Plugin onBuildContext ──────────────────────────────────────────────
405	  // Cast context to PersonaMetadata for the plugin runner (it requires a
406	  // name field which is guaranteed by loadPersonaYaml above).
407	  const personaMetaTyped = personaMeta as PersonaMetadata;
408	  context = runBuildContext(plugins, context, personaMetaTyped, suiteConfig, target);
409	
410	  // ── 4. Render frontmatter ─────────────────────────────────────────────────
411	  const fmTemplate = resolveFrontmatterTemplate(target, plugins, config.frontmatter, registry);
412	  const contentBasename = path.basename(personaYamlPath, '.yaml') + '.md';
413	  const frontmatter = renderFrontmatter(fmTemplate, context, contentBasename);
414	
415	  // ── 5. Load content template ──────────────────────────────────────────────
416	  const contentSubdir = suiteConfig.contentSubdir ?? 'content';
417	  const contentPath = path.join(suiteConfig.srcDir, contentSubdir, contentBasename);
418	  const bodyTemplate = normalizeNewlines(await readFile(contentPath, 'utf8'));
419	
420	  // ── 6. Render body ────────────────────────────────────────────────────────
421	  let body = resolvePartials(bodyTemplate, partialsMap);
422	  body = resolveConditionals(body, context);
423	  body = resolveVariables(body, context, contentBasename);
424	  body = collapseBlankLines(body);
425	  body = ensureBlankLineBeforeHeadings(body);
426	  body = body.trimEnd();
427	
428	  // ── 7. Assemble output ────────────────────────────────────────────────────
429	  let output = normalizeNewlines(`${frontmatter}\n\n${body}\n`);
430	
431	  // ── 8. Plugin onPostRender ────────────────────────────────────────────────
432	  output = runPostRender(plugins, output, personaMetaTyped, target);
433	
434	  // ── 9. Plugin onValidate ──────────────────────────────────────────────────
435	  const validationResults: ValidationResult[] = runValidate(plugins, personaMetaTyped, suiteConfig, target);
436	
437	  // ── 10. Determine output file path ────────────────────────────────────────
438	  // Resolve the registry definition once — used for both outputDirKey (map
439	  // lookup) and filenameContextKey (output filename override).
440	  const def = registry.has(target) ? registry.get(target) : undefined;
441	  const outputDir = resolveOutputDir(target, suiteConfig, def);
442	  // Use the filename context key declared in the target's registry definition,
443	  // falling back to the content basename when absent or unset in context.
444	  const fnKey = def?.filenameContextKey;
445	  const outputBasename =
446	    fnKey && typeof context[fnKey] === 'string'
447	      ? (context[fnKey] as string)
448	      : contentBasename;
449	  const outputPath = path.join(outputDir, outputBasename);
450	
451	  // ── 11. Write (unless check mode) ─────────────────────────────────────────
452	  const check = config.check ?? false;
453	  let written = false;
454	
455	  if (!check) {
456	    await mkdir(outputDir, { recursive: true });
457	    await writeFile(outputPath, output, 'utf8');
458	    written = true;
459	  }
460	
461	  return {
462	    suite: suiteName,
463	    target,
464	    personaYamlPath,
465	    outputPath,
466	    content: output,
467	    validationResults,
468	    written,
469	  };
470	}
471	
472	// ---------------------------------------------------------------------------
473	// buildSuite — all personas in one suite × one target
474	// ---------------------------------------------------------------------------
475	
476	/**
477	 * Build all personas in a suite for a single output target.
478	 *
479	 * Pipeline:
480	 *   1. Load `_shared.yaml` for the suite
481	 *   2. Load merged partials (shared → suite-local)
482	 *   3. Run `onSuiteInit` on all plugins
483	 *   4. Discover all persona YAML files
484	 *   5. Call `buildPersona()` for each
485	 *
486	 * @param suiteName    Identifier for this suite
487	 * @param suiteConfig  Suite configuration
488	 * @param config       Top-level BuildConfig
489	 * @param plugins      Registered plugins
490	 * @param target       Target output format
491	 * @param agentMap     Pre-built cross-suite agent name map
492	 * @param registry     Target registry to use. Defaults to `defaultRegistry`.
493	 *   **Two-registry limitation:** If you pass a custom `TargetRegistry` only
494	 *   to `build()` (via `config.targetRegistry`) and call `buildSuite()`
495	 *   directly without also passing that registry here, your custom targets
496	 *   will not be visible — `defaultRegistry` will be used instead. Either
497	 *   pass the same registry instance explicitly, or call `build()` to have
498	 *   the registry forwarded automatically.
499	 * @returns            Array of BuildResult objects, one per persona
500	 */
501	export async function buildSuite(
502	  suiteName: string,
503	  suiteConfig: SuiteConfig,
504	  config: BuildConfig,
505	  plugins: PersonaBuildPlugin[],
506	  target: string,
507	  agentMap: Record<string, string> = {},
508	  registry: TargetRegistry = defaultRegistry,
509	): Promise<BuildResult[]> {
510	  // ── 1. Load shared metadata ───────────────────────────────────────────────
511	  const metaSubdir = suiteConfig.metaSubdir ?? 'meta';
512	  const sharedYamlPath = path.join(suiteConfig.srcDir, metaSubdir, '_shared.yaml');
513	  const sharedMeta = await loadRawYaml(sharedYamlPath);
514	
515	  // ── 2. Load partials (two-layer: shared base → suite-local override) ──────
516	  let partialsMap: Record<string, string> = {};
517	
518	  if (config.sharedPartialsDir && existsSync(config.sharedPartialsDir)) {
519	    partialsMap = { ...partialsMap, ...(await loadPartials(config.sharedPartialsDir)) };
520	  }
521	
522	  const partialsSubdir = suiteConfig.partialsSubdir ?? 'partials';
523	  const suitePartialsDir = path.join(suiteConfig.srcDir, partialsSubdir);
524	  if (existsSync(suitePartialsDir)) {
525	    partialsMap = { ...partialsMap, ...(await loadPartials(suitePartialsDir)) };
526	  }
527	
528	  // ── 3. Plugin onSuiteInit ─────────────────────────────────────────────────
529	  runSuiteInit(plugins, suiteConfig, sharedMeta);
530	
531	  // ── 4. Discover persona YAML files ────────────────────────────────────────
532	  const personaYamlPaths = await discoverSuitePersonaYamls(suiteConfig);
533	
534	  // ── 5. Build each persona ─────────────────────────────────────────────────
535	  const results: BuildResult[] = [];
536	  for (const yamlPath of personaYamlPaths) {
537	    const result = await buildPersona(
538	      yamlPath,
539	      suiteName,
540	      suiteConfig,
541	      sharedMeta,
542	      partialsMap,
543	      config,
544	      plugins,
545	      target,
546	      agentMap,
547	      registry,
548	    );
549	    results.push(result);
550	  }

551	
552	  return results;
553	}
554	
555	// ---------------------------------------------------------------------------
556	// build — top-level entry point
557	// ---------------------------------------------------------------------------
558	
559	/**
560	 * Top-level build orchestrator.
561	 *
562	 * Iterates all `config.suites × config.targets` combinations, calls
563	 * `buildSuite()` for each, and aggregates the results into a `BuildSummary`.
564	 *
565	 * Modes:
566	 *   - Normal: renders and writes all personas.
567	 *   - `check: true`: renders without writing; useful for CI staleness checks.
568	 *   - `strict: true`: throws when any ValidationResult has severity `'error'`
569	 *     or `'warning'`. All suites are processed before the throw, so output
570	 *     files **will** be written to disk even when the build ultimately fails.
571	 *     **For CI usage, combine `strict: true` with `check: true`** to avoid
572	 *     leaving partial artefacts on disk when validation fails.
573	 *
574	 * @param config  Typed build configuration
575	 * @returns       Aggregated BuildSummary
576	 * @throws        `Error` when `strict: true` and validation failures exist
577	 */
578	export async function build(config: BuildConfig): Promise<BuildSummary> {
579	  const plugins = config.plugins ?? [];
580	  const registry = config.targetRegistry ?? defaultRegistry;
581	  // When a custom registry is supplied and targets are not explicit, build all
582	  // registered targets. When using the default registry without an explicit
583	  // targets list, build only targets with defaultEnabled !== false. This
584	  // preserves the historical two-target default (vscode + claude-code) for
585	  // existing suite configs that do not configure deep-agents output.
586	  const targets = config.targets ?? registry.names().filter(n => registry.get(n).defaultEnabled !== false);
587	  const allResults: BuildResult[] = [];
588	
589	  // Pre-scan: build cross-suite agent name map
590	  const agentMap = await buildAgentNameMap(config);
591	
592	  for (const [suiteName, suiteConfig] of Object.entries(config.suites)) {
593	    for (const target of targets) {
594	      const suiteResults = await buildSuite(suiteName, suiteConfig, config, plugins, target, agentMap, registry);
595	      allResults.push(...suiteResults);
596	    }
597	  }
598	
599	  // Collect strict failures (error + warning severity)
600	  const strictFailures: ValidationResult[] = config.strict
601	    ? allResults.flatMap((r) =>
602	        r.validationResults.filter(
603	          (v) => v.severity === 'error' || v.severity === 'warning',
604	        ),
605	      )
606	    : [];
607	
608	  const success = !config.strict || strictFailures.length === 0;
609	
610	  const summary: BuildSummary = {
611	    success,
612	    results: allResults,
613	    strictFailures,
614	    totalBuilt: allResults.length,
615	    totalWritten: allResults.filter((r) => r.written).length,
616	  };
617	
618	  if (config.strict && !success) {
619	    const messages = strictFailures.map((f) => `[${f.severity}] ${f.message}`).join('\n');
620	    throw new Error(
621	      `Build failed in strict mode — ${strictFailures.length} validation issue(s):\n${messages}`,
622	    );
623	  }
624	
625	  return summary;
626	}

